import{_ as l,a0 as p,w as o,s as r,I as t,a1 as i,A as n,x as s,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何通過命令列升級 Debian 9 為 Debian 10 | LCTT x X-CMD","titleTemplate":false,"description":"如何通過命令列升級 Debian 9 為 Debian 10 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何通過命令列升級 Debian 9 為 Debian 10 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何通過命令列升級 Debian 9 為 Debian 10 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190720 How to Upgrade Debian 9 (Stretch) to Debian 10 (Buster) via Command Line","title":"如何通過命令列升級 Debian 9 為 Debian 10","tag":"201908","desc":""},"relativePath":"201908/20190720 How to Upgrade Debian 9 (Stretch) to Debian 10 (Buster) via Command Line.md","filePath":"[post].md"}'),u={name:"201908/20190720 How to Upgrade Debian 9 (Stretch) to Debian 10 (Buster) via Command Line.md"};function b(h,a,g,c,k,D){const e=p("Link");return o(),r("div",null,[t("p",null,[i(e,{href:"collector:",title:"lujun9972"},{default:n(()=>[...a[0]||(a[0]=[s("#",-1)])]),_:1}),a[5]||(a[5]=s(": subject: (How to Upgrade Debian 9 (Stretch) to Debian 10 (Buster) via Command Line) ",-1)),i(e,{href:"collector:",title:"lujun9972"},{default:n(()=>[...a[1]||(a[1]=[s("#",-1)])]),_:1}),a[6]||(a[6]=s(": via: (",-1)),i(e,{href:"https://www.linuxtechi.com/upgrade-debian-9-to-debian-10-command-line/"},{default:n(()=>[...a[2]||(a[2]=[s("https://www.linuxtechi.com/upgrade-debian-9-to-debian-10-command-line/",-1)])]),_:1}),a[7]||(a[7]=s(") ",-1)),i(e,{href:"collector:",title:"lujun9972"},{default:n(()=>[...a[3]||(a[3]=[s("#",-1)])]),_:1}),a[8]||(a[8]=s(": author: (Pradeep Kumar ",-1)),i(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...a[4]||(a[4]=[s("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),a[9]||(a[9]=s(")",-1))]),a[28]||(a[28]=t("h1",{id:"如何通過命令列升級-debian-9-為-debian-10",tabindex:"-1"},[s("如何通過命令列升級 Debian 9 為 Debian 10 "),t("a",{class:"header-anchor",href:"#如何通過命令列升級-debian-9-為-debian-10","aria-label":"Permalink to “如何通過命令列升級 Debian 9 為 Debian 10”"},"​")],-1)),t("p",null,[a[11]||(a[11]=s("我們已經在先前的文章中看到如何安裝 ",-1)),i(e,{href:"https://linux.cn/article-11083-1.html"},{default:n(()=>[...a[10]||(a[10]=[s("Debian 10（Buster）",-1)])]),_:1}),a[12]||(a[12]=s("。今天，我們將學習如何從 Debian 9 升級為 Debian 10，雖然我們已將看到 Debian 10 和它的特色，所以這裏我們不會深入介紹。但是可能讀者沒有機會讀到那篇文章，讓我們快速瞭解一下 Debian 10 和它的新功能。",-1))]),a[29]||(a[29]=d(`<p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Upgrade-Debian-9-to-Debian-10.jpg" alt=""></p><p>在差不多兩年的開發後，Debian 團隊最終發佈一個穩定版本，Debian 10 的代碼名稱是 Buster。Buster 是一個 LTS (長期支持支持)版本，因此未來將由 Debian 支持 5 年。</p><h3 id="debian-10-buster-新的特色" tabindex="-1">Debian 10（Buster）新的特色 <a class="header-anchor" href="#debian-10-buster-新的特色" aria-label="Permalink to “Debian 10（Buster）新的特色”">​</a></h3><p>Debian 10（Buster）回報給大多數 Debian 愛好者大量的新特色。一些特色包括：</p><ul><li>GNOME 桌面 3.30</li><li>默認啓用 AppArmor</li><li>支持 Linux 內核 4.19.0-4</li><li>支持 OpenJDk 11.0</li><li>從 Nodejs 4 ~ 8 升級到 Nodejs 10.15.2</li><li>Iptables 替換為 NFTables</li></ul><p>等等。</p><h3 id="從-debian-9-到-debian-10-的逐步升級指南" tabindex="-1">從 Debian 9 到 Debian 10 的逐步升級指南 <a class="header-anchor" href="#從-debian-9-到-debian-10-的逐步升級指南" aria-label="Permalink to “從 Debian 9 到 Debian 10 的逐步升級指南”">​</a></h3><p>在我們開始升級 Debian 10 前，讓我們看看升級需要的必備條件：</p><h4 id="步驟-1-debian-升級必備條件" tabindex="-1">步驟 1) Debian 升級必備條件 <a class="header-anchor" href="#步驟-1-debian-升級必備條件" aria-label="Permalink to “步驟 1) Debian 升級必備條件”">​</a></h4><ul><li>一個良好的網絡連接</li><li>root 用户權限</li><li>數據備份</li></ul><p>備份你所有的應用程序代碼庫、數據文件、用户賬號詳細信息、配置文件是極其重要的，以便在升級出錯時，你可以總是可以還原到先前的版本。</p><h4 id="步驟-2-升級-debian-9-現有的軟件包" tabindex="-1">步驟 2) 升級 Debian 9 現有的軟件包 <a class="header-anchor" href="#步驟-2-升級-debian-9-現有的軟件包" aria-label="Permalink to “步驟 2) 升級 Debian 9 現有的軟件包”">​</a></h4><p>接下來的步驟是升級你所有現有的軟件包，因為一些軟件包被標誌為保留不能升級，從 Debian 9 升級為 Debian 10 有失敗或引發一些問題的可能性。所以，我們不冒任何風險，更好地升級軟件包。使用下面的代碼來升級軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><h4 id="步驟-3-修改軟件包存儲庫文件-etc-sources-list" tabindex="-1">步驟 3) 修改軟件包存儲庫文件 /etc/sources.list <a class="header-anchor" href="#步驟-3-修改軟件包存儲庫文件-etc-sources-list" aria-label="Permalink to “步驟 3) 修改軟件包存儲庫文件 /etc/sources.list”">​</a></h4><p>接下來的步驟是修改軟件包存儲庫文件 <code>/etc/sources.list</code>，你需要用文本 <code>Buster</code> 替換 <code>Stretch</code>。</p><p>但是，在你更改任何東西前，確保如下創建一個 <code>sources.list</code> 文件的備份：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo cp /etc/apt/sources.list /etc/apt/sources.list.bak</span></span></code></pre></div><p>現在使用下面的 <code>sed</code> 命令來在軟件包存儲庫文件中使用 <code>buster</code> 替換 <code>stretch</code>，示例如下顯示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo sed -i &#39;s/stretch/buster/g&#39; /etc/apt/sources.list</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo sed -i &#39;s/stretch/buster/g&#39; /etc/apt/sources.list.d/*.list</span></span></code></pre></div><p>更新後，你需要如下更新軟件包存儲庫索引：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span></code></pre></div><p>在開始升級你現有的 Debian 操作系統前，讓我們使用下面的命令驗證當前版本，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ cat /etc/*-release</span></span>
<span class="line"><span>PRETTY_NAME=&quot;Debian GNU/Linux 9 (stretch)&quot;</span></span>
<span class="line"><span>NAME=&quot;Debian GNU/Linux&quot;</span></span>
<span class="line"><span>VERSION_ID=&quot;9&quot;</span></span>
<span class="line"><span>VERSION=&quot;9 (stretch)&quot;</span></span>
<span class="line"><span>ID=debian</span></span>
<span class="line"><span>HOME_URL=&quot;https://www.debian.org/&quot;</span></span>
<span class="line"><span>SUPPORT_URL=&quot;https://www.debian.org/support&quot;</span></span>
<span class="line"><span>BUG_REPORT_URL=&quot;https://bugs.debian.org/&quot;</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><h4 id="步驟-4-從-debian-9-升級到-debian-10" tabindex="-1">步驟 4) 從 Debian 9 升級到 Debian 10 <a class="header-anchor" href="#步驟-4-從-debian-9-升級到-debian-10" aria-label="Permalink to “步驟 4) 從 Debian 9 升級到 Debian 10”">​</a></h4><p>你做完所有的更改後，是時候從 Debian 9 升級到 Debian 10 了。但是在這之前，再次如下確保更新你的軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><p>在軟件包升級期間，你將被提示啓動服務，所以選擇你較喜歡的選項。</p><p>一旦你係統的所有軟件包升級完成，就升級你的發行版的軟件包。使用下面的代碼來升級發行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt dist-upgrade -y</span></span></code></pre></div><p>升級過程可能花費一些時間，取決於你的網絡速度。記住在升級過程中，你將被詢問一些問題，在軟件包升級後是否需要重啓服務、你是否需要保留現存的配置文件等。如果你不想進行一些自定義更改，簡單地鍵入 “Y” ，來讓升級過程繼續。</p><h4 id="步驟-5-驗證升級" tabindex="-1">步驟 5) 驗證升級 <a class="header-anchor" href="#步驟-5-驗證升級" aria-label="Permalink to “步驟 5) 驗證升級”">​</a></h4><p>一旦升級過程完成，重啓你的機器，並使用下面的方法檢測版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ lsb_release -a</span></span></code></pre></div><p>如果你獲得如下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Distributor ID: Debian</span></span>
<span class="line"><span>Description:    Debian GNU/Linux 10 (buster)</span></span>
<span class="line"><span>Release:        10</span></span>
<span class="line"><span>Codename:       buster</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>是的，你已經成功地從 Debian 9 升級到 Debian 10。</p><p>驗證升級的備用方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ cat /etc/*-release</span></span>
<span class="line"><span>PRETTY_NAME=&quot;Debian GNU/Linux 10 (buster)&quot;</span></span>
<span class="line"><span>NAME=&quot;Debian GNU/Linux&quot;</span></span>
<span class="line"><span>VERSION_ID=&quot;10&quot;</span></span>
<span class="line"><span>VERSION=&quot;10 (buster)&quot;</span></span>
<span class="line"><span>VERSION_CODENAME=buster</span></span>
<span class="line"><span>ID=debian</span></span>
<span class="line"><span>HOME_URL=&quot;https://www.debian.org/&quot;</span></span>
<span class="line"><span>SUPPORT_URL=&quot;https://www.debian.org/support&quot;</span></span>
<span class="line"><span>BUG_REPORT_URL=&quot;https://bugs.debian.org/&quot;</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><h3 id="結束" tabindex="-1">結束 <a class="header-anchor" href="#結束" aria-label="Permalink to “結束”">​</a></h3><p>希望上面的逐步指南為你提供了從 Debian 9（Stretch）簡單地升級為 Debian 10（Buster）的所有信息。在評論部分，請給予你使用 Debian 10 的反饋、建議、體驗。</p><hr>`,42)),t("p",null,[a[14]||(a[14]=s("via: ",-1)),i(e,{href:"https://www.linuxtechi.com/upgrade-debian-9-to-debian-10-command-line/"},{default:n(()=>[...a[13]||(a[13]=[s("https://www.linuxtechi.com/upgrade-debian-9-to-debian-10-command-line/",-1)])]),_:1})]),t("p",null,[a[19]||(a[19]=s("作者：",-1)),i(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...a[15]||(a[15]=[s("Pradeep Kumar",-1)])]),_:1}),a[20]||(a[20]=s(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[16]||(a[16]=[s("lujun9972",-1)])]),_:1}),a[21]||(a[21]=s(" 譯者：",-1)),i(e,{href:"https://github.com/robsean"},{default:n(()=>[...a[17]||(a[17]=[s("robsean",-1)])]),_:1}),a[22]||(a[22]=s(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[18]||(a[18]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[25]||(a[25]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[23]||(a[23]=[s("LCTT",-1)])]),_:1}),a[26]||(a[26]=s(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...a[24]||(a[24]=[s("Linux中國",-1)])]),_:1}),a[27]||(a[27]=s(" 榮譽推出",-1))])])}const w=l(u,[["render",b]]);export{x as __pageData,w as default};
